import{_ as t,a as o,b as n,c as a,d as r,e as s,f as i,g as d,h as l}from"./chunks/technic-light-runtime.BM1alCex.js";import{_ as c,o as g,c as p,a3 as h}from"./chunks/framework.BlfGB29P.js";const x=JSON.parse('{"title":"Technic","description":"Install the external Technic widget set and connect Window – Wall to Home Assistant.","frontmatter":{"title":"Technic","description":"Install the external Technic widget set and connect Window – Wall to Home Assistant."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/technic.md","filePath":"en/projects/grafik-visual-studio/technic.md","lastUpdated":1792849697000}'),u={name:"en/projects/grafik-visual-studio/technic.md"};function m(b,e,w,f,y,v){return g(),p("div",null,[...e[0]||(e[0]=[h('<h1 id="technic" tabindex="-1">Technic <a class="header-anchor" href="#technic" aria-label="Permalink to &quot;Technic&quot;">​</a></h1><p>From <strong>Studio 0.1.296</strong>, the thermostat offers initially disabled <a href="./ha-quellen-climate">Climate controls</a>: two targets, HVAC modes, presets, fan, swing, humidity and power according to device capabilities. Widget properties and runtime messages support DE/EN/FR; existing settings remain valid.</p><p>Packages and helper tools are provided centrally at <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. This open-source page provides descriptions and instructions; downloads are provided by the package catalog.</p><p><strong>Inspired by the <a href="https://github.com/Sefina-DS/ioBroker.vis-2-widgets-technic" target="_blank" rel="noreferrer">ioBroker Technic Widgets by Sefina-DS</a>.</strong> An independent implementation for Home Assistant.</p><p>From <strong>Studio 0.1.203</strong>, you can install <strong>Technic 1.6.0</strong>. The package contains all seven widget types: <strong>Window – Wall</strong>, <strong>Switch – Boolean</strong>, <strong>Dimmer – Light</strong>, <strong>Room – Overlay</strong>, <strong>Clock – Date</strong>, <strong>Thermostat – Temperature</strong> and <strong>Status – List</strong>. Install 1.6.0 through package management as an additive update to previous versions; existing widgets are preserved.</p><h2 id="status-–-list" tabindex="-1">Status – List <a class="header-anchor" href="#status-–-list" aria-label="Permalink to &quot;Status – List&quot;">​</a></h2><p><img src="'+t+'" alt="Status list showing temperature and window state, simulated HA test data"></p><p>The status list displays up to <strong>ten read-only status rows</strong>. The default is <strong>0 rows</strong>, leaving the widget empty. Default size: <strong>160 × 120 pixels</strong>. Under <strong>Status rows</strong>, configure the count, <strong>value column offset (90 px)</strong> and <strong>container left padding (8 px)</strong>. The offset defines the label column width; the value column follows after a 4 px gap. Container left padding is added to the fixed 8 px inset.</p><p>The count reveals <strong>Status row [1]</strong> through <strong>[10]</strong>. Each row has a label and a Home Assistant entity. <strong>Number</strong> supports units, decimals and number color. <strong>Boolean</strong> supports ON/OFF text and colors, plus comma-separated additional entities with <strong>AND</strong> or <strong>OR</strong>. Original fields <code>oid1</code> through <code>oid10</code> map to Studio&#39;s <code>rowEntityId1</code> through <code>rowEntityId10</code>; <code>oidsExtra1</code> through <code>oidsExtra10</code> map to <code>extraEntityIds1</code> through <code>extraEntityIds10</code>.</p><p>Missing, unknown and unavailable inputs remain <code>—</code>. Font size, family, bold and label color inherit <strong>CSS → Font and Text</strong>. Long labels or values use ellipsis, with full text in tooltips. Increase widget width for long units; the screenshot uses 240 pixels. Overflowing rows scroll inside the widget. Clicks never write HA states or hide labels. All row settings and spacing remain in project and widget exports.</p><h2 id="thermostat-–-temperature" tabindex="-1">Thermostat – Temperature <a class="header-anchor" href="#thermostat-–-temperature" aria-label="Permalink to &quot;Thermostat – Temperature&quot;">​</a></h2><p><img src="'+o+'" alt="Temperature dial after a setpoint change; the caption remains visible"></p><p>The thermostat displays target/actual temperature, humidity, actuator and cooling mode. Default size: <strong>220 × 220 pixels</strong>, range <strong>15–28</strong>, step <strong>0.5</strong>. <strong>General</strong> controls the caption, visibility, top/bottom position, icon scale and read-only mode. <strong>Dial</strong> controls bounds and step; <strong>Colors</strong> provides ON, OFF and cooling colors.</p><table tabindex="0"><thead><tr><th>Original field</th><th>Studio binding</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_temp_soll</code></td><td>Target temperature</td><td><code>climate</code> with a single setpoint or <code>input_number</code></td></tr><tr><td><code>oid_temp_ist</code></td><td>Actual temperature</td><td>Temperature sensor or <code>climate.current_temperature</code></td></tr><tr><td><code>oid_feuchtigkeit</code></td><td>Humidity</td><td>Percentage sensor or <code>climate.current_humidity</code></td></tr><tr><td><code>oid_stellmotor</code></td><td>Actuator</td><td>Sensor 0–100%, Boolean state or <code>climate.hvac_action</code></td></tr><tr><td><code>oid_kuehlmodus</code></td><td>Cooling mode</td><td>Boolean state or a <code>climate</code> cooling state</td></tr></tbody></table><p>Blank read bindings use matching attributes of the target <code>climate</code> entity. An <code>input_number</code> target needs separate sensors. Heating/cooling activity means <strong>100%</strong>, idle/off <strong>0%</strong>; this is not a measured valve position. Missing or unavailable readings remain <code>—</code>.</p><p>In runtime, drag the <strong>300° arc</strong> or use the keyboard range. Release commits once through <code>climate.set_temperature</code> or <code>input_number.set_value</code>. The server first checks current HA capabilities, bounds and both step grids. Incompatible grids, unknown states, read-only mode and editor operation never write. Only the setpoint changes; operating mode and power are not changed. HA failures show a status message; the caption remains visible.</p><p><img src="'+n+'" alt="Seven-day target/actual temperature history and separate actuator axis; simulated test data"></p><p><strong>History</strong> opens <strong>24 hours</strong> or <strong>7 days</strong> from <strong>Home Assistant Recorder</strong>. Target and actual use the temperature axis; actuator uses the right percentage axis. Configure the three colors under <strong>History (HA Recorder)</strong>. Unknown readings break the curve. Recorder must track the selected entities and retain data for the requested period. HA Recorder replaces the ioBroker <code>influxInstance</code> setting. All bindings, display settings and colors remain in project and widget exports. The screenshots were captured locally with simulated HA responses.</p><h2 id="clock-–-date" tabindex="-1">Clock – Date <a class="header-anchor" href="#clock-–-date" aria-label="Permalink to &quot;Clock – Date&quot;">​</a></h2><p><img src="'+a+'" alt="Running clock with seconds and a German date"></p><p>The clock displays the <strong>browser&#39;s local time and timezone</strong> without an HA entity. It updates every second without redrawing other widgets; after a paused browser tab resumes, it reads the current time again.</p><p>Under <strong>General</strong>, choose side-by-side/stacked layout, left/center/right alignment, gap, optional background, corner radius and padding. Default size is 260 × 90 pixels. Long dates or large fonts require more space; overflowing content remains scrollable.</p><p>Under <strong>Time</strong>, configure visibility, 12/24-hour format, seconds, color, font size and bold text. The 12-hour format uses AM/PM. Under <strong>Date</strong>, configure visibility, color, font size and bold text independently.</p><p>Date language is independent of the Studio language: German, English, French, Spanish, Italian or Dutch. Choose Day-Month-Year, Month-Day-Year or Year-Month-Day; dot/hyphen/slash/space separators; numeric/short/long months; four/two-digit years; and an optional leading zero for the day. Weekdays can be hidden, short or long. Month and weekday names come from browser locale data. All options remain in project and widget exports.</p><h2 id="room-–-overlay" tabindex="-1">Room – Overlay <a class="header-anchor" href="#room-–-overlay" aria-label="Permalink to &quot;Room – Overlay&quot;">​</a></h2><p><img src="'+r+'" alt="Room tile with preserved caption and an open Studio target page"></p><p>The room tile displays a custom <strong>room name</strong> and up to <strong>ten status rows</strong>. Configure name color, font size, bold text, horizontal and vertical alignment, and padding on each side. Default size: 160 × 100 pixels.</p><p>Under <strong>Status rows</strong>, select the count, font size and label color. Rows can be arranged vertically or horizontally with a separator and gap. The corresponding <strong>Status row [1]</strong> through <strong>[10]</strong> groups appear according to the count.</p><p>Each row has a label and a Home Assistant entity. <strong>Number</strong> supports units, decimal places and number color. <strong>True / False</strong> supports ON/OFF text and colors plus comma-separated additional entities combined with <strong>AND</strong> or <strong>OR</strong>. Missing, unknown or unavailable inputs display <code>—</code>; they never report OFF. Data is read only.</p><p>Under <strong>Click behavior / Popup</strong>, select an existing <strong>Studio target page</strong>. <strong>Popup</strong> opens its runtime in a dialog; <strong>Switch page</strong> navigates directly. Recreate an ioBroker view as a Studio page first. Invalid targets, self references and recursive embedding cannot open a popup. In the editor, clicking only selects the widget.</p><p>Configure popup width and height, a fixed X/Y position instead of centering, background, border color, width and radius. Outside-click closing, the close button and automatic closing after a number of seconds are configurable (<code>0</code> = off). <strong>Escape</strong> always closes it. Live updates preserve the open popup and caption. Navigating away or removing the tile closes the dialog. Dimensions are constrained to the viewport. All settings remain in project and widget exports.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Download <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=en" target="_blank" rel="noreferrer">ugso.technic.wg</a>. Open <strong>Settings → Widget packages → Install local .wg / .wg.zip</strong> and select the file. After reloading, the set appears with an automatically assigned unused color. It remains independent of built-in widgets and Weather and Heating.</p><p>The <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/technic" target="_blank" rel="noreferrer">source and reproducible package build</a> are public. The download includes <code>README.md</code> and <code>LICENSE.txt</code>, including the full MIT license and original attribution <code>Copyright (c) 2026 Sefina-DS</code>.</p><h2 id="window-–-wall" tabindex="-1">Window – Wall <a class="header-anchor" href="#window-–-wall" aria-label="Permalink to &quot;Window – Wall&quot;">​</a></h2><p><strong>General</strong> configures the caption, <strong>Show caption</strong>, top/bottom caption position, icon size (10–100%), left/right handle and icon color. The default size is 120 × 160 pixels. <strong>Read only</strong> disables control.</p><p><strong>Data points</strong> provides three independent HA bindings:</p><table tabindex="0"><thead><tr><th>Original field</th><th>Studio field</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_kontakt</code></td><td>Opening contact: entity</td><td>for example <code>binary_sensor.garage_window</code>; <code>on</code> means open</td></tr><tr><td><code>oid_rollo</code></td><td>Blind: cover entity</td><td>for example <code>cover.garage_blind</code>; reads <code>current_position</code></td></tr><tr><td><code>oid_modus</code></td><td>Mode: entity</td><td>for example <code>input_boolean.blind_manual</code>; off = automatic, on = manual</td></tr></tbody></table><p>Each binding has its own inversion. <strong>Invert blind</strong> reverses both display and written position (<code>100 − position</code>). Normally 0 means closed and 100 means open. Unknown values remain unknown after inversion. The contact is read-only. An optional <strong>A/M</strong> symbol displays the mode; <code>?</code> indicates an unknown mode.</p><p><img src="'+s+'" alt="Installed Technic set and HA bindings in the editor"></p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p>In runtime, clicking the window opens a dialog with a position slider, quick values <strong>0 / 25 / 50 / 75 / 100%</strong> and an optional mode toggle. Keyboard control is supported; Escape or <strong>Close</strong> dismisses the dialog. The blind action uses only <code>cover.set_cover_position</code> for the selected entity. Availability and SET_POSITION support in <code>supported_features</code> are checked before writing. Mode writes only target available <code>input_boolean</code> or <code>switch</code> entities. Sensors remain read-only displays.</p><p>The mode helper represents the switch only: configure the actual blind automation in Home Assistant. No automation is generated or disabled. Failed actions display a retry message; pending actions are not sent twice.</p><p><img src="'+i+'" alt="Runtime dialog with blind position and mode controls"></p><h2 id="switch-–-boolean" tabindex="-1">Switch – Boolean <a class="header-anchor" href="#switch-–-boolean" aria-label="Permalink to &quot;Switch – Boolean&quot;">​</a></h2><p>The switch follows the configuration options of <code>tplTechnicSchalterBoolean</code>. Defaults: <strong>Device</strong>, caption visible at the bottom, 120 × 160 pixels, Power symbol at 80%, ON color <code>#2dd4b0</code>, OFF color <code>#5f8f8a</code>.</p><p><strong>Entity (ON/OFF)</strong> binds the HA entity. <strong>Value type → True / False</strong> reads <code>on</code>/<code>off</code> and controls available <code>switch</code>, <code>light</code> or <code>input_boolean</code> entities using <code>turn_on</code>/<code>turn_off</code>. <strong>0 / 1</strong> accepts only 0 and 1 and writes numbers to an <code>input_number</code> helper. Its limits and step must allow both values. Sensors remain display-only; unknown, missing or unavailable states cannot be switched.</p><p><strong>Select icon</strong> offers all 16 symbol types: selection, desktop PC, power, bed lamp, hanging lamp, round hanging lamp, desk lamp, spots, RGB LED strip, table lamp, link, fan, key, smartphone, socket and TV. These are original geometric SVG drawings rather than copied graphic traces. ON/OFF colors and size are configurable. Selection shows its check mark only when ON.</p><p>Click the symbol in the runtime to toggle; the caption stays visible. Tab and Enter/Space support keyboard operation. <strong>Read-only</strong> blocks changes. Pending actions cannot be sent twice; failures show a message and allow retry. <strong>ON (preview)</strong> applies only to unbound editor widgets. All settings remain in project and widget exports.</p><p><img src="'+d+'" alt="Switch after turning on with its caption still visible"></p><h2 id="dimmer-–-light" tabindex="-1">Dimmer – Light <a class="header-anchor" href="#dimmer-–-light" aria-label="Permalink to &quot;Dimmer – Light&quot;">​</a></h2><p>Follows the options of <code>tplTechnicReglerLicht</code>: caption <strong>Light</strong>, visible at the bottom, icon size 80%, 160 × 200 pixels. <strong>ON color</strong> is <code>#2ecfbf</code>, <strong>OFF color</strong> <code>#5f8f8a</code>, <strong>Dimmer background</strong> <code>#0d1820</code>. Size, colors and caption placement are configurable; the graphic is an independent SVG implementation.</p><p><strong>On/Off: entity</strong> accepts <code>light</code>, <code>switch</code> or <code>input_boolean</code>. <strong>Brightness: entity (0–100)</strong> accepts a dimmable <code>light</code> entity or an <code>input_number</code> helper. For a normal HA light, enter <strong>the same light entity in both fields</strong>. The host converts HA <code>brightness</code> from 0–255 to percent. OFF displays 0%. A numeric helper should use min = 0, max = 100 and step = 1. Sensors can display values but are never written.</p><p><strong>Link power and brightness</strong> is enabled by default: ON sets 100%, OFF sets 0%, dimming above zero turns ON. Both bindings must be available and writable. Binding the same light generates one HA call. Without linking, separate bindings remain independent; an HA brightness action using <code>light.turn_on</code> still turns that light on. 0% uses <code>light.turn_off</code>.</p><p>Drag the outer radial arc or use the range control with the keyboard. The value previews locally while dragging and is sent only on release. The center power button toggles ON/OFF. The caption stays visible. <strong>Read-only</strong> blocks actions; unknown or non-dimmable entities cannot be operated. Missing live values never use preview fallbacks. <strong>ON (preview)</strong> and <strong>Brightness (preview)</strong> apply only to unbound editor widgets.</p><p>The host validates all targets before the first write. Separate entities use sequential HA calls; a provider error can partially apply an action. Error feedback asks you to check the state before retrying. Pending actions cannot be sent twice. Operation was tested with simulated HA entities; real hardware needs separate verification.</p><p><img src="'+l+'" alt="Runtime light dimmer at 50 percent with its caption visible"></p><h2 id="preview-and-export" tabindex="-1">Preview and export <a class="header-anchor" href="#preview-and-export" aria-label="Permalink to &quot;Preview and export&quot;">​</a></h2><p><strong>Preview</strong> provides open-window, blind-position and manual-mode values. These apply only to unbound displays in the editor. Bound entities use live values. In runtime, unbound or missing values remain unknown and never use preview fallbacks. Editor clicks never trigger HA control actions.</p><p>All display settings, three entity bindings, inversions, preview values and read-only state remain in project and widget exports. Verification used simulated HA entities; real blind control needs testing with your hardware.</p>',60)])])}const T=c(u,[["render",m]]);export{x as __pageData,T as default};
